// Static export has no image optimizer, so next/image picks from sizes pre-generated by scripts/prepare-media.mjs:
// /media/<slug>-<w>.webp for 320–1600 px, and the 2560 px /media/<slug>.jpg as the largest.
// The widths match images.deviceSizes + images.imageSizes in next.config.ts.
const basePath = process.env.NEXT_PUBLIC_BASE_PATH ?? "";
const widths = [320, 640, 1080, 1600];

export default function imageLoader({ src, width }: { src: string; width: number }) {
  if (!src.startsWith("/media/") || !src.endsWith(".jpg")) return `${basePath}${src}`;
  const w = widths.find((v) => v >= width);
  // ?w= on the full-size file only satisfies Next's dev check that loaders vary by width; static hosts ignore it.
  return `${basePath}${w ? src.replace(/\.jpg$/, `-${w}.webp`) : `${src}?w=${width}`}`;
}
